// tests/fixtures/plugins/kanban/main.ts
var button = (text, action, payload) => ({
  type: "button",
  text,
  action,
  payload
});
var databases = (api) => api.call("database.list").filter((d) => d.properties.some((p) => p.type === "status" || p.type === "select"));
function current(api) {
  const all = databases(api);
  return all.find((d) => d.id === api.state.databaseId) || all[0];
}
function status(db) {
  return db.properties.find((p) => p.type === "status" || p.type === "select");
}
var main_default = {
  onEvent(api) {
    api.state.updated = Date.now();
  },
  commands: {
    open(api) {
      api.openView("board");
    },
    summary(api) {
      return databases(api).map((d) => ({
        id: d.id,
        name: d.name,
        total: api.call("query.run", { databaseId: d.id, limit: 1 }).total
      }));
    }
  },
  views: {
    board: {
      render(api) {
        const all = databases(api), db = current(api);
        if (!db)
          return {
            type: "stack",
            children: [
              { type: "text", text: "\uC0C1\uD0DC \uCEEC\uB7FC\uC774 \uC788\uB294 \uB370\uC774\uD130\uBCA0\uC774\uC2A4\uB97C \uB9CC\uB4E4\uBA74 \uCE78\uBC18\uC73C\uB85C \uAD00\uB9AC\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4." },
              button("\uC0C8 \uBCF4\uB4DC \uB9CC\uB4E4\uAE30", "create")
            ]
          };
        const property = status(db), title = db.properties.find((p) => p.type === "text");
        const result = api.call("query.run", { databaseId: db.id, limit: 200 });
        const states = [
          .../* @__PURE__ */ new Set([
            ...property.options || [],
            ...result.rows.map((r) => String(r.values[property.id] ?? "\uBBF8\uC9C0\uC815"))
          ])
        ];
        if (!states.length) states.push("\uBBF8\uC9C0\uC815");
        return {
          type: "stack",
          children: [
            {
              type: "row",
              children: [
                ...all.map((d) => button(d.name, "database", d.id)),
                button("\uC0C8 \uBCF4\uB4DC \uB9CC\uB4E4\uAE30", "create")
              ]
            },
            {
              type: "row",
              children: [
                {
                  type: "input",
                  label: "\uC0C8 \uCE74\uB4DC \uC81C\uBAA9",
                  action: "draft",
                  value: String(api.state.draft ?? ""),
                  placeholder: "\uD560 \uC77C\uC744 \uC785\uB825\uD558\uACE0 Enter"
                },
                button("\uCE74\uB4DC \uCD94\uAC00", "add", db.id)
              ]
            },
            {
              type: "text",
              tone: "muted",
              text: `${result.total}\uAC1C \uCE74\uB4DC${result.total > 200 ? " \xB7 \uCC98\uC74C 200\uAC1C \uD45C\uC2DC" : ""}`
            },
            {
              type: "grid",
              columns: Math.min(states.length, 7),
              children: states.map((state) => ({
                type: "stack",
                children: [
                  {
                    type: "heading",
                    text: `${state} \xB7 ${result.rows.filter((r) => String(r.values[property.id] ?? "\uBBF8\uC9C0\uC815") === state).length}`
                  },
                  ...result.rows.filter((r) => String(r.values[property.id] ?? "\uBBF8\uC9C0\uC815") === state).map(
                    (row) => ({
                      type: "card",
                      children: [
                        {
                          type: "text",
                          text: String(title ? row.values[title.id] || "\uC81C\uBAA9 \uC5C6\uC74C" : row.id)
                        },
                        {
                          type: "select",
                          label: "\uCE74\uB4DC \uC0C1\uD0DC",
                          action: "status",
                          value: state,
                          options: states,
                          payload: { id: row.id, revision: row.revision, property: property.id }
                        },
                        button(row.bodyNoteId ? "\uBCF8\uBB38 \uC5F4\uAE30" : "\uBCF8\uBB38 \uB9CC\uB4E4\uAE30", "body", {
                          id: row.id,
                          revision: row.revision
                        })
                      ]
                    })
                  )
                ]
              }))
            }
          ]
        };
      },
      onAction(api, action) {
        if (action.id === "create") {
          const db = api.call("database.create", {
            name: String(api.settings["board-name"]),
            properties: [
              { id: "title", name: "\uC774\uB984", type: "text" },
              { id: "status", name: "\uC0C1\uD0DC", type: "status", options: ["\uD560 \uC77C", "\uC9C4\uD589 \uC911", "\uC644\uB8CC"] }
            ]
          });
          api.state.databaseId = db.id;
        }
        if (action.id === "database") api.state.databaseId = String(action.payload);
        if (action.id === "draft") api.state.draft = String(action.value);
        if (action.id === "add") {
          const db = current(api);
          if (!db) return;
          const title = db.properties.find((p) => p.type === "text");
          if (!title) {
            api.notify("\uD14D\uC2A4\uD2B8 \uCEEC\uB7FC\uC744 \uBA3C\uC800 \uCD94\uAC00\uD558\uC138\uC694.");
